function purchaseCard(c){const when=c.event_at?new Date(c.event_at).toLocaleString('en-IN'):'',amount=Number(c.amount||0),rate=Number(c.actual_rate||0),side=c.message_side==='outgoing'?'outgoing':'incoming';return '<article class="work-card purchase-card '+side+'"><h2>'+safe(c.purchase_kind==='MATCHING_CLOTH'?'Matching Purchase':'CB Purchase')+' · '+safe(cbLabel(c.cb_code||c.cb_no||c.lot_no))+'</h2><div class="action-note">'+safe(c.message||'Purchase confirmed')+'</div><div class="grid"><span>Supplier <b>'+safe(c.supplier||'—')+'</b></span><span>Bill <b>'+safe(c.bill_no||'—')+'</b></span><span>Fabric <b>'+safe(c.fabric_name||'—')+'</b></span><span>कपड़ा <b>'+Number(c.quantity||0)+' '+safe(c.quantity_unit||'KG')+'</b></span><span>Rolls <b>'+Number(c.roll_count||0)+'</b></span><span>Rate <b>'+(rate?'₹'+rate.toLocaleString('en-IN'):'—')+'</b></span><span>Amount <b>'+(amount?'₹'+amount.toLocaleString('en-IN'):'—')+'</b></span><span>Status <b>'+safe(friendlyStatus(c.source_status))+'</b></span>'+'</div>'+thumb(c)+purchaseChildren(c)+'<p>'+safe(c.sender_name||'Purchase Team')+' → '+safe(c.receiver_name||'Purchase')+' '+tick(c)+'</p></article>'}
function cbDepartmentCard(c){const due=Number(c.pending_material_count||0),state=String(c.source_status||'OPEN').toUpperCase(),materials=arr(c.materials),children=arr(c.cb_children),next=arr(c.next_actions),role=String(S.actor?.role||S.actor?.role_code||'').toUpperCase(),canEdit=['OWNER','SUPER_ADMIN','ADMIN'].includes(role),edit=canEdit&&(state==='OPEN'||due>0)?'<a data-action="CB_EDIT" href="'+safe(c.edit_href)+'">'+(state==='OPEN'?'EDIT / DRAFT SAVE':'UPDATE DUE MATERIAL')+'</a>':'',mapped=next.filter(a=>!arr(a.allowed_roles).length||arr(a.allowed_roles).map(x=>String(x).toUpperCase()).includes(role)).map(a=>'<a data-action="'+safe(a.code||'CB_NEXT_ACTION')+'" href="'+safe(a.href)+'" title="Existing engine: '+safe(a.engine||'canonical')+'">'+safe(a.label||a.code)+'</a>').join(''),actions=edit||mapped?'<div class="card-actions">'+edit+mapped+'</div>':'',materialRows=materials.length?'<section class="cb-children"><h3>ADDITIONAL MATERIAL</h3>'+materials.map(m=>'<div class="cb-child"><span><b>'+safe(m.name)+'</b><small>'+safe(m.state)+' · Qty '+(m.qty==null?'—':safe(m.qty))+' '+safe(m.unit||'UNIT DUE')+'</small></span></div>').join('')+'</section>':'',childRows=children.length?'<section class="cb-children"><h3>D CARD DECISIONS</h3>'+children.map(x=>'<div class="cb-child"><span><b>'+safe(x.cb_code)+'</b><small>'+safe(String(x.state||'').replaceAll('_',' '))+' · Art '+safe(x.art_status||'DUE')+' · Print '+safe(x.print_status||'WAITING')+' · Sticker '+safe(x.sticker_status||'WAITING')+' · Metal ID '+safe(x.metal_id_status||'WAITING')+'</small></span></div>').join('')+'</section>':'',ready=Number(c.cutting_ready_count||0),released=Number(c.released_child_count||0),unavailable=Number(c.unavailable_child_count||0),artDue=Number(c.art_due_count||0),cutting=unavailable&&Number(c.available_child_count||0)===0?'NOT AVAILABLE':artDue?'WAITING FOR ART / COMBO':due>0?'HOLD · '+due+' MATERIAL DUE':ready>0?'READY FOR CUTTING · '+ready+' READY'+(released?' · '+released+' RELEASED':''):released>0?'RELEASED':'PENDING',when=c.event_at?new Date(c.event_at).toLocaleString('en-IN'):'';return '<article class="work-card purchase-card" data-event-key="'+safe(c.event_key)+'" data-cb-no="'+safe(c.cb_no)+'" data-search="'+safe([c.cb_no,c.fabric_name,c.supplier,state,cutting,'CB Department'].join(' ').toLowerCase())+'"><h2>CB '+safe(cbLabel(c.cb_no))+'</h2><div class="action-note">'+safe(c.message)+'</div><div class="grid"><span>Regular Cloth <b>'+safe(c.quantity??'—')+' '+safe(c.quantity_unit||'KG')+'</b></span><span>Supplier <b>'+safe(c.supplier||'—')+'</b></span><span>Fabric <b>'+safe(c.fabric_name||'—')+'</b></span><span>Divisions <b>'+safe(c.division_count)+'</b></span><span>Colours <b>'+safe(c.colour_count)+'</b></span><span>Art / Crafting <b>'+safe(c.art_status)+'</b></span><span>Art Combo <b>'+safe(c.art_combo_status)+'</b></span><span>Pending Material <b>'+due+'</b></span><span>CB Status <b>'+safe(state)+'</b></span><span>Cutting Status <b>'+safe(cutting)+'</b></span>'+(when?'<span>समय <b>'+safe(when)+'</b></span>':'')+'</div>'+childRows+materialRows+actions+'</article>'}
function flowCard(c){const when=c.event_at?new Date(c.event_at).toLocaleString('en-IN'):'',side=c.message_side==='outgoing'?'outgoing':'incoming',cut=String(c.card_type||'').includes('CUTTING'),ready=c.card_type==='READY_FOR_CUTTING',done=String(c.source_status||'').toUpperCase()==='COMPLETED',heading=ready?'CB '+safe(cbLabel(c.cb_code||c.cb_no)):cut?(c.lot_no&&c.lot_no!=='—'?'Lot '+safe(c.lot_no):'Cutting · '+safe(cbLabel(c.cb_code||c.cb_no))):'Art Decide · '+safe(cbLabel(c.cb_code||c.cb_no)),cloth=c.quantity!=null&&Number(c.quantity)>0?'<span>कपड़ा <b>'+Number(c.quantity)+' '+safe(c.quantity_unit||'KG')+'</b></span>':'',ci=c.craft_identity||c;return '<article class="work-card '+side+'"><h2>'+heading+'</h2><div class="action-note">'+safe(c.message||'')+'</div><div class="grid"><span>CB <b>'+safe(cbLabel(c.cb_code||c.cb_no))+'</b></span>'+(ci.art_no&&!/MAPPING REQUIRED/i.test(String(ci.art_no))?'<span>Art <b>'+safe(ci.art_no)+'</b></span>':'')+(ci.print_no&&!/^(N\/?A|MAPPING REQUIRED)$/i.test(String(ci.print_no))?'<span>Print <b>'+safe(ci.print_no)+'</b></span>':'')+(ci.frame_no&&!/^(N\/?A|FRAME MAPPING REQUIRED|MAPPING REQUIRED)$/i.test(String(ci.frame_no))?'<span>Frame <b>'+safe(ci.frame_no)+'</b></span>':'')+(ci.sticker_no&&!/^(N\/?A|NA)$/i.test(String(ci.sticker_no))?'<span>Sticker <b>'+safe(ci.sticker_name||ci.sticker_no)+'</b></span>':'')+(ci.metal_id_no&&!/^(N\/?A|NA)$/i.test(String(ci.metal_id_no))?'<span>Metal ID <b>'+safe(ci.metal_id_name||ci.metal_id_no)+'</b></span>':'')+cloth+(c.roll_count!=null?'<span>Rolls <b>'+Number(c.roll_count||0)+'</b></span>':'')+'<span>स्थिति <b>'+safe(done?'Complete':friendlyStatus(c.source_status))+'</b></span>'+(when?'<span>समय <b>'+safe(when)+'</b></span>':'')+'</div>'+thumb(c)+'<p>'+safe(c.sender_name||'Workflow')+' → '+safe(c.receiver_name||c.department_name)+' '+tick(c)+'</p>'+actionButtons(c)+'</article>'}
function identityAudit(c){if(String(c.source_module||'').toUpperCase()==='UPM_MISSING_CLAIM'&&(c.responsible_name||c.performer_name||c.assigner_name||c.receiver_name)){const parts=[['Performer',c.performed_by_name||c.performer_name],['Act As',c.act_as_name],['Assigner',c.assigner_name],['Receiver',c.receiver_name],['Responsible',c.responsible_name]].filter(([,v])=>String(v||'').trim());return '<div class="audit">'+parts.map(([k,v])=>safe(k)+' <b>'+safe(v)+'</b>').join(' · ')+'</div>'}return c.performed_by_name&&c.on_behalf_of_name?'<div class="audit">'+safe(c.on_behalf_of_name)+' की ओर से '+safe(c.performed_by_name)+' ने किया</div>':''}
function card(c,small=false){let inner;if(c.source_module==='CB_DEPARTMENT')inner=cbDepartmentCard(c);else if(['CB_PURCHASE','MATCHING_PURCHASE'].includes(c.source_module))inner=purchaseCard(c);else if(['ART_DECIDE','READY_FOR_CUTTING','CUTTING_RELEASED'].includes(c.card_type))inner=flowCard(c);else{const isDamage=c.card_type==='DAMAGE_CASE'||/^DAMAGE_/.test(String(c.source_event_type||c.source_status||'').toUpperCase()),canSeeRate=['OWNER','SUPER_ADMIN','ADMIN','MANAGER'].includes(String(S.actor?.role||S.actor?.role_code||'').toUpperCase()),rate=Number(c.actual_rate)>0?'₹'+Number(c.actual_rate).toLocaleString("en-IN"):"—",who=c.worker_name?' · '+safe(c.worker_name):'',when=c.event_at?new Date(c.event_at).toLocaleString('en-IN'):'',sent=c.vendor_message_sent_at?new Date(c.vendor_message_sent_at).toLocaleString('en-IN'):'',sender=c.sender_name||'Workflow',receiver=c.receiver_name,relation=receiver&&receiver.toLowerCase()!==sender.toLowerCase()?safe(sender)+' → '+safe(receiver):safe(sender),note=c.message?'<div class="action-note">'+safe(c.message)+'</div>':'',audit=identityAudit(c),side=c.message_side==='outgoing'?'outgoing':'incoming',unit=String(isDamage?'KG':(c.quantity_unit||c.unit_label||'PCS')).toUpperCase(),shown={...c,quantity_unit:unit,unit_label:unit};inner='<article class="work-card '+side+'" data-event-key="'+safe(c.event_key||'')+'" data-assignment-id="'+safe(c.assignment_id||'')+'" data-side="'+side+'" data-search="'+safe([c.lot_no,c.cb_code,c.cb_no,c.art_no,c.worker_name,c.department_name,c.colour_name,c.source_status,c.message].join(" ").toLowerCase())+'"><h2>Lot '+safe(c.lot_no)+who+'</h2>'+note+'<div class="grid">'+(c.cb_code||c.cb_no?'<span>CB <b>'+safe(c.cb_code||c.cb_no)+'</b></span>':'')+(c.craft_identity?.art_no?'<span>Art <b>'+safe(c.craft_identity.art_no)+'</b></span>':'')+(c.craft_identity?.print_no&&!/^(N\/?A|NA)$/i.test(String(c.craft_identity.print_no))?'<span>Print <b>'+safe(c.craft_identity.print_no)+'</b></span>':'')+(c.craft_identity?.frame_no&&!/^(N\/?A|NA|FRAME MAPPING REQUIRED)$/i.test(String(c.craft_identity.frame_no))?'<span>Frame <b>'+safe(c.craft_identity.frame_no)+'</b></span>':'')+(c.craft_identity?.sticker_no&&!/^(N\/?A|NA)$/i.test(String(c.craft_identity.sticker_no))?'<span>Sticker <b>'+safe(c.craft_identity.sticker_name||c.craft_identity.sticker_no)+'</b></span>':'')+(c.craft_identity?.metal_id_no&&!/^(N\/?A|NA)$/i.test(String(c.craft_identity.metal_id_no))?'<span>Metal ID <b>'+safe(c.craft_identity.metal_id_name||c.craft_identity.metal_id_no)+'</b></span>':'')+'<span>काम <b>'+safe(c.department_name)+'</b></span><span>'+safe(unit==='PCS'?'पीस':'मात्रा')+' <b>'+safe(quantityText(shown))+'</b></span>'+(!small&&!isDamage&&canSeeRate&&Number(c.actual_rate)>0?'<span>रेट <b>'+rate+'</b></span>':'')+'<span>स्थिति <b>'+safe(friendlyStatus(c.source_status))+'</b></span>'+(when?'<span>दिनांक / समय <b>'+safe(when)+'</b></span>':'')+(c.supplier_name?'<span>Supplier <b>'+safe(c.supplier_name)+'</b></span>':'')+(c.supplier_phone_last4?'<span>WhatsApp <b>••••'+safe(c.supplier_phone_last4)+'</b></span>':'')+(sent?'<span>Sent <b>'+safe(sent)+'</b></span>':'')+(when?'<span>समय <b>'+safe(when)+'</b></span>':'')+'</div>'+thumb(c)+'<p>'+relation+' '+tick(c)+'</p>'+audit+actionButtons(c)+'</article>'}return S.status==='CLOSE'?closedRow(c,inner):inner}
function countFor(x){return Number((S.workCounts?.[x.department_code]??(S.status==="OPEN"?x.open_count:S.status==="CLOSE"?x.close_count:x.working_count))||0)}
function syncStatusButtons(){document.querySelectorAll('[data-status],[data-chat-status]').forEach(x=>{const status=x.dataset.status||x.dataset.chatStatus;x.classList.toggle('on',status===S.status);x.textContent=S.search?status+' '+Number(S.searchCounts[status]||0):status})}
function renderActive(active=S.active){active?.kind==='division'?openDivision(Number(active.id),false):active?.kind==='workflow'?openWorkflow(...active.id.split(':').map(Number),false):active?.kind==='department'?openDepartment(active.id,false):active?.kind==='group'||active?.kind==='person'?openChat(active.kind,active.id,false,active.parentDepartment):inbox()}
function changeStatus(status){S.searchAutoSelect=false;S.searchFocusPending=!!S.search;if(status===S.status){focusSearchCard(true,true);return}S.searchFocusIndex=-1;const previous=S.status;history.replaceState({...((history.state)||{view:'inbox'}),status:previous},'',viewUrl(previous));S.status=status;history.pushState({...((history.state)||{view:'inbox'}),status},'',viewUrl(status));syncStatusButtons();const rows=$('chat')&&!$('chat').hidden?$('chatRows'):$('rows');if(rows)rows.innerHTML='<div class="empty">'+safe(status)+' load हो रहा है…</div>';load(true)}
function inbox(){S.active=null;if(window.RR_ON_BEHALF_ACTIVE&&!['OWNER','SUPER_ADMIN','ADMIN','MANAGER','DEPARTMENT_HEAD','CUTTING_MASTER','LINE_MANAGER','LINE_MAN'].includes(String(S.actor?.role||S.actor?.role_code||'').toUpperCase())&&S.departments.length===1){return openDepartment(S.departments[0].department_code,false)}let h='<h3>ALL DEPARTMENTS</h3>';for(const d of S.departments)h+='<button class="row" data-department="'+safe(d.department_code)+'"><i>👥</i><span><b>'+safe(d.department_name)+' Department</b><small>'+Number(d.worker_count||0)+' workers · '+Number(d.staff_count||0)+' staff · '+countFor(d)+' '+S.status.toLowerCase()+' updates</small></span><strong class="go">›</strong></button>';h+='<div class="list-end">✓ '+S.departments.length+' departments · '+S.people.length+' people mapped</div>';$('rows').innerHTML=h;$('chat').hidden=true;$('inbox').hidden=false;document.querySelectorAll('[data-department]').forEach(b=>b.onclick=()=>openDepartment(b.dataset.department))}
function renderDrawer(){let h='';MODULES.forEach((g,gi)=>{h+='<div class="drawer-section">'+safe(g.title)+'</div><button data-division="'+gi+'"><b>'+safe(g.title)+'</b></button>';g.items.forEach((x,ii)=>h+='<button data-workflow="'+gi+':'+ii+'">'+safe(x[0])+'</button>')});$('drawerRows').innerHTML=h;document.querySelectorAll('[data-division]').forEach(b=>b.onclick=()=>openDivision(Number(b.dataset.division)));document.querySelectorAll('[data-workflow]').forEach(b=>b.onclick=()=>{const [g,i]=b.dataset.workflow.split(':').map(Number);openWorkflow(g,i)})}
function openDivision(gi,push=true){$('drawer').hidden=true;const g=MODULES[gi];if(g.title==='Real Chat Directory')return inbox();S.active={kind:'division',id:String(gi)};$('rows').innerHTML='<h3>'+safe(g.title.toUpperCase())+'</h3>'+g.items.map((x,i)=>'<button class="row" data-module-row="'+i+'"><i>💬</i><span><b>'+safe(x[0])+'</b><small>Module group and relevant personal messages</small></span><strong class="go">›</strong></button>').join('');$('chat').hidden=true;$('inbox').hidden=false;document.querySelectorAll('[data-module-row]').forEach(b=>b.onclick=()=>openWorkflow(gi,Number(b.dataset.moduleRow)));if(push)pushCurrentView({view:'division',id:String(gi),status:S.status})}
const MC1_DRAFT_KEY='RR_MC1_PURCHASE_DRAFT_V504';
const mc1Uuid=()=>globalThis.crypto?.randomUUID?.()||'00000000-0000-4000-8000-'+Date.now().toString().padStart(12,'0').slice(-12);
function mc1DraftRead(){try{return JSON.parse(localStorage.getItem(MC1_DRAFT_KEY)||'null')}catch{return null}}
function mc1DraftWrite(v){if(v)localStorage.setItem(MC1_DRAFT_KEY,JSON.stringify(v));else localStorage.removeItem(MC1_DRAFT_KEY)}
function mc1Money(v){return v==null?'Restricted':commercialMoney(v)}
function mc1Kg(v){return Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:3,maximumFractionDigits:3})+' KG'}
function mc1Css(){if(document.getElementById('rrMc1V504Style'))return;const s=document.createElement('style');s.id='rrMc1V504Style';s.textContent='.mcv504-head{padding:9px 11px;border:1px solid #594836;border-radius:12px;background:#201a13;color:#f3d98f;margin-bottom:9px;font-weight:900}.mcv504-card{border:1px solid #3b4654;border-radius:14px;background:#101820;padding:11px;margin:8px 0}.mcv504-card h3{margin:0 0 7px;font-size:15px}.mcv504-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.mcv504-grid label{font-size:11px;color:#adbac8}.mcv504-grid input,.mcv504-grid select,.mcv504-grid textarea{display:block;width:100%;min-height:42px;margin-top:4px;padding:8px;border:1px solid #405061;border-radius:9px;background:#09111a;color:#fff}.mcv504-full{grid-column:1/-1}.mcv504-metrics{display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px}.mcv504-metrics span{padding:7px;border-radius:8px;background:#182431}.mcv504-actions{display:flex;gap:7px;margin-top:9px}.mcv504-actions button{flex:1;min-height:42px;border:1px solid #5d7187;border-radius:10px;background:#183149;color:#fff;font-weight:900}.mcv504-actions .confirm{background:#8d2f3d;border-color:#d05a69}.mcv504-note{color:#9fb0c1;font-size:11px;margin-top:7px}.mcv504-ok{color:#80ddb0}.mcv504-bad{color:#ff9aa5}@media(max-width:430px){.mcv504-grid,.mcv504-metrics{grid-template-columns:1fr}.mcv504-full{grid-column:auto}}';document.head.appendChild(s)}
function mc1PurchaseCard(c){return '<article class="mcv504-card"><h3>'+safe(c.fabric_name)+' · STOCK IN</h3><div class="mcv504-metrics"><span>Vendor <b>'+safe(c.vendor_name)+'</b></span><span>Bill <b>'+safe(c.bill_no)+'</b></span><span>Qty <b>'+mc1Kg(c.qty)+'</b></span><span>Rate <b>'+mc1Money(c.rate)+'</b></span><span>Value <b>'+mc1Money(c.value)+'</b></span><span>Account <b>Matching Cloth Purchase</b></span></div><p class="mcv504-note">Confirmed '+safe(c.posted_at?new Date(c.posted_at).toLocaleString('en-IN'):'')+' · Supplier Ledger linked</p></article>'}
function mc1ConsumptionCard(c){return '<article class="mcv504-card"><h3>LOT '+safe(c.lot_no)+' · '+safe(c.fabric_name)+'</h3><div class="mcv504-metrics"><span>Actual Used <b>'+mc1Kg(c.qty)+'</b></span><span>Avg Rate <b>'+mc1Money(c.rate)+'/KG</b></span><span>Matching Cost <b>'+mc1Money(c.value)+'</b></span><span>Source <b>MC1</b></span></div><p class="mcv504-note mcv504-ok">Consumption recorded · '+safe(c.movement_count||1)+' canonical movement</p></article>'}
function mc1ClosingCard(c){return '<article class="mcv504-card"><h3>'+safe(c.fabric_name)+' · MC1</h3><div class="mcv504-metrics"><span>Purchase IN <b>'+mc1Kg(c.total_purchase_in)+'</b></span><span>Consumption OUT <b>'+mc1Kg(c.total_consumption_out)+'</b></span><span>GR / Adjustment <b>'+mc1Kg(c.gr_adjustment)+'</b></span><span>Closing Qty <b>'+mc1Kg(c.closing_qty)+'</b></span><span>W.Avg Rate <b>'+mc1Money(c.avg_rate)+'/KG</b></span><span>Closing Value <b>'+mc1Money(c.closing_value)+'</b></span></div><div class="mcv504-actions"><button type="button" data-mc-history="'+safe(c.fabric_id)+'">VIEW HISTORY</button></div><div data-mc-history-host="'+safe(c.fabric_id)+'"></div></article>'}
function mc1DraftForm(fabrics,vendors,draft={}){const fopts=fabrics.map(f=>'<option value="'+safe(f.id||f.matching_item_id)+'" '+(String(draft.fabric_id||'')===String(f.id||f.matching_item_id)?'selected':'')+'>'+safe(f.fabric_name)+' · '+mc1Kg(f.available_qty??f.current_qty)+'</option>').join(''),vopts=vendors.map(v=>'<option value="'+safe(v.supplier_ledger_id)+'" data-name="'+safe(v.vendor_name)+'" '+(String(draft.supplier_ledger_id||'')===String(v.supplier_ledger_id)?'selected':'')+'>'+safe(v.vendor_name)+'</option>').join('');return '<article class="mcv504-card" data-mc-draft><h3>NEW PURCHASE / STOCK IN</h3><div class="mcv504-grid"><label>Matching Fabric<select data-mc-fabric><option value="">Select Existing</option>'+fopts+'<option value="__new__" '+(draft.new_fabric?'selected':'')+'>+ Add New Fabric</option></select></label><label>New Fabric Name<input data-mc-new-fabric value="'+safe(draft.new_fabric||'')+'" placeholder="Only for Add New"></label><label>Vendor<select data-mc-vendor><option value="">Select Mapped Vendor</option>'+vopts+'<option value="__new__" '+(draft.new_vendor?'selected':'')+'>+ Add New Vendor</option></select></label><label>New Vendor Name<input data-mc-new-vendor value="'+safe(draft.new_vendor||'')+'" placeholder="Only for Add New"></label><label>Bill No.<input data-mc-bill value="'+safe(draft.bill_no||'')+'"></label><label>Bill Date<input data-mc-date type="date" value="'+safe(draft.bill_date||new Date().toISOString().slice(0,10))+'"></label><label>Qty KG<input data-mc-qty type="number" min="0.001" step="0.001" value="'+safe(draft.qty||'')+'"></label><label>Rate / KG<input data-mc-rate type="number" min="0.01" step="0.01" value="'+safe(draft.rate||'')+'"></label><label>Bill Value<input data-mc-value type="number" min="0.01" step="0.01" value="'+safe(draft.value||'')+'"></label><label class="mcv504-full">Remarks<textarea data-mc-remarks>'+safe(draft.remarks||'')+'</textarea></label></div><p class="mcv504-note">Save Draft से stock/accounting post नहीं होगा. Confirm Save पर ही canonical MC1 purchase post होगी.</p><div class="mcv504-actions"><button type="button" data-mc-save-draft>SAVE DRAFT</button></div><p data-mc-state class="mcv504-note"></p></article>'}
function mc1SavedDraft(d){return '<article class="mcv504-card" data-mc-draft><h3>DRAFT · '+safe(d.fabric_name)+'</h3><div class="mcv504-metrics"><span>Vendor <b>'+safe(d.vendor_name)+'</b></span><span>Bill <b>'+safe(d.bill_no)+'</b></span><span>Qty <b>'+mc1Kg(d.qty)+'</b></span><span>Rate <b>'+commercialMoney(d.rate)+'/KG</b></span><span>Value <b>'+commercialMoney(d.value)+'</b></span><span>Status <b>NOT POSTED</b></span></div><div class="mcv504-actions"><button type="button" data-mc-edit>EDIT</button><button class="confirm" type="button" data-mc-confirm>CONFIRM SAVE</button></div><p data-mc-state class="mcv504-note">Correction अभी possible है. Confirm के बाद canonical stock/account posting होगी.</p></article>'}
function mc1ReadDraftForm(host,fabrics,vendors){const fabric=host.querySelector('[data-mc-fabric]'),vendor=host.querySelector('[data-mc-vendor]'),newFabric=host.querySelector('[data-mc-new-fabric]').value.trim(),newVendor=host.querySelector('[data-mc-new-vendor]').value.trim(),qty=Number(host.querySelector('[data-mc-qty]').value||0),rate=Number(host.querySelector('[data-mc-rate]').value||0),typedValue=Number(host.querySelector('[data-mc-value]').value||0),value=typedValue>0?typedValue:qty*rate,fr=fabrics.find(x=>String(x.id||x.matching_item_id)===fabric.value),vr=vendors.find(x=>String(x.supplier_ledger_id)===vendor.value);if(fabric.value==='__new__'&&!newFabric)throw Error('New Matching Fabric Name required.');if(fabric.value!=='__new__'&&!fr)throw Error('Existing Matching Fabric select karein.');if(vendor.value==='__new__'&&!newVendor)throw Error('New Vendor Name required.');if(vendor.value!=='__new__'&&!vr)throw Error('Mapped Vendor select karein.');if(!host.querySelector('[data-mc-bill]').value.trim())throw Error('Bill No required.');if(!(qty>0)||!(value>0))throw Error('Valid Qty and Rate / Value required.');return{idempotency_key:mc1DraftRead()?.idempotency_key||mc1Uuid(),stage:'SAVED',fabric_id:fr?(fr.id||fr.matching_item_id):null,fabric_name:fr?.fabric_name||newFabric,new_fabric:fabric.value==='__new__'?newFabric:'',supplier_ledger_id:vr?.supplier_ledger_id||null,vendor_name:vr?.vendor_name||newVendor,new_vendor:vendor.value==='__new__'?newVendor:'',bill_no:host.querySelector('[data-mc-bill]').value.trim().toUpperCase(),bill_date:host.querySelector('[data-mc-date]').value,qty,rate:value/qty,value,remarks:host.querySelector('[data-mc-remarks]').value.trim()}}
function bindMc1Draft(fabrics,vendors,rerender){const host=$('messages').querySelector('[data-mc-draft]');if(!host)return;host.querySelector('[data-mc-save-draft]')?.addEventListener('click',()=>{const state=host.querySelector('[data-mc-state]');try{const d=mc1ReadDraftForm(host,fabrics,vendors);mc1DraftWrite(d);rerender(d)}catch(e){state.textContent=err(e);state.classList.add('mcv504-bad')}});host.querySelector('[data-mc-edit]')?.addEventListener('click',()=>{const d=mc1DraftRead()||{};d.stage='EDIT';mc1DraftWrite(d);rerender(d)});host.querySelector('[data-mc-confirm]')?.addEventListener('click',async e=>{const d=mc1DraftRead(),state=host.querySelector('[data-mc-state]');if(!d)return;const b=e.currentTarget;b.disabled=true;b.textContent='POSTING…';try{const result=await rpc('rr_confirm_mc_purchase_v504',{p_idempotency_key:d.idempotency_key,p_fabric_id:d.fabric_id||null,p_fabric_name:d.fabric_name,p_supplier_ledger_id:d.supplier_ledger_id||null,p_vendor_name:d.vendor_name,p_bill_no:d.bill_no,p_bill_qty:d.qty,p_bill_value:d.value,p_bill_date:d.bill_date,p_remarks:d.remarks||null});mc1DraftWrite(null);state.textContent=result?.duplicate_blocked?'✓ Already posted · duplicate blocked':'✓ Canonical purchase posted once';state.classList.add('mcv504-ok');await openMc1Chat(S.active.mcGroup,S.active.mcItem,false)}catch(ex){state.textContent=err(ex);state.classList.add('mcv504-bad');b.disabled=false;b.textContent='CONFIRM SAVE'}})}
