function openDepartment(id,push=true){S.active={kind:'department',id};const d=S.departments.find(x=>x.department_code===id);if(!d)return inbox();$('chatName').textContent=d.department_name+' Department';$('kind').textContent='DEPARTMENT DIRECTORY';$('manageStaffAction').hidden=!membershipAdminRole();$('manageStaffAction').onclick=()=>openMembershipAdmin(id);let h='<button class="row group-entry" data-dept-group="'+safe(id)+'"><i>💬</i><span><b>'+safe(id==='PURCHASE'?'CB Department':d.department_name)+' Group Chat</b><small>'+countFor(d)+' mapped '+S.status.toLowerCase()+' updates</small></span><strong class="go">›</strong></button><h3>WORKER SIDE · '+Number(d.worker_count||0)+'</h3>';h+=arr(d.workers).map(x=>memberRow(x,'WORKER')).join('')||'<div class="empty">No home worker mapped.</div>';h+='<h3>REDZED STAFF SIDE · '+Number(d.staff_count||0)+'</h3>'+(arr(d.staff).map(x=>memberRow(x,'STAFF')).join('')||'<div class="empty">No RedZed staff mapped.</div>');$('messages').innerHTML=h;$('inbox').hidden=true;$('chat').hidden=false;document.querySelector('[data-dept-group]').onclick=()=>openChat('group',id);document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>openChat('person',b.dataset.person,true,id));if(push)pushCurrentView({view:'department',department:id,status:S.status})}
